9	use PHPStan\Rules\RuleErrorBuilder;
10	
11	/**
12	 * Collects control-flow violations from one test method body.
13	 */
14	final class TestMethodControlFlowErrorCollector
15	{
16	    /** @readonly */
17	    private ControlFlowTypeResolver $typeResolver;
18	
19	    /** @readonly */
20	    private NestedScopeFilter $nestedScopeFilter;
21	
22	    /**
23	     * Creates a collector from type resolution and nested-scope filtering.
24	     */
25	    public function __construct(
26	        ?ControlFlowTypeResolver $typeResolver = null,
27	        ?NestedScopeFilter $nestedScopeFilter = null,
28	    ) {
29	        $this->typeResolver = $typeResolver ?? new ControlFlowTypeResolver();
30	        $this->nestedScopeFilter = $nestedScopeFilter ?? new NestedScopeFilter();
31	    }
32	
33	    /**
34	     * @param array<\PhpParser\Node\Stmt> $stmts
35	     * @return list<IdentifierRuleError>
36	     */
37	    public function errors(array $stmts, string $methodName): array
38	    {
39	        $nodeFinder = new NodeFinder();
40	        $violations = $nodeFinder->find($stmts, function (\PhpParser\Node $node): bool {
41	            return $this->typeResolver->type($node) !== null;
42	        });
43	
44	        $filtered = $this->nestedScopeFilter->filter($violations, $stmts);
45	
46	        $errors = [];
47	        foreach ($filtered as $node) {
48	            $statementType = $this->typeResolver->type($node);
49	            if ($statementType === null) {
50	                continue;
51	            }
52	
53	            $errors[] = RuleErrorBuilder::message(
54	                sprintf(
55	                    'Split test method %s() so it contains no "%s" statement. Use separate tests or a data provider for each case.',
56	                    $methodName,
57	                    $statementType
58	                )
59	            )
60	                ->identifier('customRules.testMethodControlFlow')
61	                ->line($node->getStartLine())
62	                ->build();
63	        }
64	
65	        return $errors;
66	    }
67	}
